Actionscript.script:
onClipEvent(enterFrame){
speed = 5
if(Key.isDown(Key.UP)){
this._y-=speed;
}

if(Key.isDown(Key.DOWN)){
this._y+=speed;
}

if(Key.isDown(Key.LEFT)){
this._x-=speed;
}

if(Key.isDown(Key.RIGHT)){
this._x+=speed;
}

if(_x >= Stage.width){
_x -=speed
}
if(_x <= 0){
_x +=speed
}
if(_y >= Stage.height){
_y -=speed
}
if(_y <= 0){
_y +=speed
}
}

