stop();
cursor1.startDrag("true");
Mouse.hide();

//Settings
cursor1.startDrag("true");
Mouse.hide();

var bulletOffset:Number = 0; //pixels - bigger number = less acurate
var bulletSpeed:Number = 7; //pixels
var reloadSpeed:Number = 100; //ms 1000 = 1 second

//Declare variables that are going to be reusing
//(this saves them in memory thus speeding everything up a little)
var reloadTimer:Number;
var reloadComplete:Boolean = true;
var bulletAngle:Number;
var randomNum:Number;
var playerX:Number;
var playerY:Number;
var rotationDirection:Number;

/**
*
* Fire Weapon
*
*/
function fireWeapon():Void
{
	//check if weapon is reloaded, if true, fire bullet
	if(reloadComplete == true)
	{
		//attach bullet
		var bullet_mc:MovieClip = _root.attachMovie("bullet", "b"+_root.getNextHighestDepth(), _root.getNextHighestDepth());

		//position bullet on player
		bullet_mc._x = player_mc._x;
		bullet_mc._y = player_mc._y;

		bullet_mc.bulletLifeTimer = 0;

		//calculate random bullet offset.
		randomNum = random(bulletOffset)-(bulletOffset/2);

		//set bullet firing angle
		bulletAngle = ((player_mc._rotation+randomNum-90)*Math.PI/180);
		bullet_mc.xSpeed = Math.cos(bulletAngle)*bulletSpeed;
		bullet_mc.ySpeed = Math.sin(bulletAngle)*bulletSpeed;

		//make it move
		bullet_mc.onEnterFrame = function() {
			//move bullet             
			this._x += this.xSpeed;
			this._y += this.ySpeed;

			//remove enemy+bullet

			if (this.hitTest(_root.enemy)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy);
			}
			if (this.hitTest(_root.enemy1)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy1);
			}
			if (this.hitTest(_root.enemy2)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy2);
			}
			if (this.hitTest(_root.enemy3)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy3);
			}
			if (this.hitTest(_root.enemy4)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy4);
			}
			if (this.hitTest(_root.enemy5)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy5);
			}
			if (this.hitTest(_root.enemy6)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy6);
			}
			if (this.hitTest(_root.enemy7)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy7);
			}
			if (this.hitTest(_root.enemy8)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy8);
			}
			if (this.hitTest(_root.enemy9)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy9);
			}
			if (this.hitTest(_root.enemy10)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy10);
			}
			if (this.hitTest(_root.enemy11)) {
           		{_root.gotoAndPlay("game2");}

			}
			if (this.hitTest(_root.enemy12)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy12);
			}
			if (this.hitTest(_root.enemy13)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy13);
			}
			if (this.hitTest(_root.enemy14)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy14);
			}
			if (this.hitTest(_root.enemy15)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy15);
			}
			if (this.hitTest(_root.enemy16)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy16);
			}
			if (this.hitTest(_root.enemy17)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy17);
			}
			if (this.hitTest(_root.enemy18)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy18);
			}
			if (this.hitTest(_root.enemy19)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy19);
			}
			if (this.hitTest(_root.enemy20)) {
				this.removeMovieClip();
				unloadMovie(_root.enemy20);
			}

			//update bullet timer 
			this.bulletLifeTimer++;
		};
		//start reloading gun
		startReloading();
	}
}

//start reloading weapon 
function startReloading()
{
	reloadComplete = false;
	//set a timer that will call the gunReloaded function after "reloadSpeed" time passes
	reloadTimer = setInterval(this, "gunReloaded", reloadSpeed);
}
//gun reloaded function - clears timers and sets reloaded to true
function gunReloaded()
{
	clearInterval(reloadTimer);
	reloadComplete = true;

}
//Rotate Player
function rotatePlayer()
{
	//update our player location parameters
	playerX = player_mc._x;
	playerY = player_mc._y;

	//calculate player_mc rotation, based on player position & mouse position 
	rotationDirection = Math.round(180 - ((Math.atan2(_root._xmouse - playerX, _root._ymouse - playerY)) * 180/Math.PI));

	//set rotation
	player_mc._rotation = rotationDirection;	
}

/**
*
* Mouse Controls
*
*/
//create an object that we'll listen to
mouseListener = new Object();

//on Click, fire the weapon
mouseListener.onMouseDown = function() {
	fireWeapon();
};

//on mouse move, rotate the player
mouseListener.onMouseMove = function() {
	rotatePlayer();
}

//add listener
Mouse.addListener(mouseListener); 
